const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point1 = ee.Geometry.Point([-58.944881, 50.282684]);
  const point2 = ee.Geometry.Point([-54.128047, 50.415337]);
  const date = '2019-09-01';

  // 2. Data Acquisition - Sentinel-2 for water color analysis
  let s2Col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(date, '2019-09-02')
    .filterBounds(ee.Geometry.Point([-58.944881, 50.282684]))
    .filterBounds(ee.Geometry.Point([-54.128047, 50.415337]));

  const colSize = s2Col.size().getInfo();
  console.log(`Sentinel-2 Images: ${colSize}`);

  if (colSize === 0) {
    console.log("No Sentinel-2 data found.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Get least cloudy image
  const image = s2Col.sort('CLOUDY_PIXEL_PERCENTAGE').first();

  // 3. Calculate Normalized Difference Turbidity Index (NDTI)
  // NDTI = (Red - Green)/(Red + Green) - higher values = more turbid/milky
  const ndti = image.normalizedDifference(['B4', 'B3']).rename('NDTI');

  // 4. Extract values at both points
  const scale = 1000;

  const val1 = ndti.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point1,
    scale: scale,
    maxPixels: 1e9
  }).get('NDTI').getInfo();

  const val2 = ndti.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point2,
    scale: scale,
    maxPixels: 1e9
  }).get('NDTI').getInfo();

  // Check for valid pixels
  const count1 = image.select('B3').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point1,
    scale: scale,
    maxPixels: 1e9
  }).get('B3').getInfo();

  const count2 = image.select('B3').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point2,
    scale: scale,
    maxPixels: 1e9
  }).get('B3').getInfo();

  console.log(`Point1 NDTI: ${val1 !== null ? val1.toFixed(4) : 'null'}, Pixels: ${count1}`);
  console.log(`Point2 NDTI: ${val2 !== null ? val2.toFixed(4) : 'null'}, Pixels: ${count2}`);

  // 5. Validation & Final Answer
  if (val1 === null || val2 === null || count1 === 0 || count2 === 0) {
    console.log("<answer>C2</answer>");
  } else if (isNaN(val1) || isNaN(val2) || val1 > 1 || val1 < -1 || val2 > 1 || val2 < -1) {
    console.log("<answer>C3</answer>");
  } else if (val1 > val2) {
    console.log("Point1 is more milky (higher NDTI)");
    console.log("<answer>A</answer>");
  } else {
    console.log("Point2 is more milky or equal");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
